          text: "Gewonnen aus dem Schwarzen Bilsenkraut, einer Nachtschattenpflanze mit stark berauschender, das Verhalten enthemmender Wirkung. In ihrer Signatur liegt ein verzweifeltes Ringen um Aufmerksamkeit und Liebe: Eifersucht, das Bedürfnis, gesehen zu werden, und die Angst, verlassen oder übergangen zu werden. Genau das prägt das Mittelbild der Zwei – das starke Verlangen nach Nähe, Anerkennung und Gebrauchtwerden. Das Bedürfnis, geliebt zu werden, wird so groß, dass die eigene Mitte darüber aus dem Blick gerät.",
