          title: "Typ 5 · Grundkarte",
          intro: "Die Typ-5-Grundkarte bildet die gemeinsame Grundlage aller Fünfer-Subtypen. Im Zentrum stehen Verstehen, Wissen und das Wahren der eigenen Ressourcen. Der Körper organisiert sich auf Beobachtung, Distanz und sparsame Energie.",
