          text: "Die Tollkirsche ist eine Nachtschattenpflanze, deren Bild von Hitze, Fieber, Fülle und glühender Erregung geprägt ist. Diese Signatur durchzieht das Mittelbild: eine fiebrige Intensität, ein Drang nach lebhaften, starken Eindrücken und ein rasches Aufflammen. Genau das lebt in der Sieben – das Bedürfnis, Schmerz zu vermeiden und das Leben in vollen Zügen zu erleben, getragen von einem fiebrigen Drang nach mehr Möglichkeiten, Reizen und Genuss. Wie das Fieber will alles hell, schnell und intensiv sein.",
