          goal: "Homöopathisch unterstützt es die Regulation dort, wo sich die Lebenskraft als Vernebelung, Selbstvergessenheit und das Abtauchen aus der eigenen Präsenz zeigt. Es hilft, wieder klarer und wacher gegenwärtig zu werden. So darf die Neun aus dem Nebel auftauchen und sich selbst wieder spüren.",
