export const remedyGlossary = {
  "Kalium sulfuricum": "Das Schüßler-Salz Nr. 6 ist das Salz des Stoffwechsels, der Entgiftung und der inneren Erneuerung. Es unterstützt die Zellatmung und hilft dem Körper, Verbrauchtes auszuscheiden und sich zu regenerieren. Auf seelischer Ebene steht es für Erneuerung und das Lösen von Festgefahrenem. Für die Eins, die sich in Strenge, Druck und Selbstverurteilung verhärten kann, fördert es einen lebendigen Fluss. So wirkt es dort, wo starre Kontrolle sich in gesunde Durchlässigkeit wandeln darf.",
  "Kalium chloratum": "Das Schüßler-Salz Nr. 4 wirkt auf Schleimhäute und Drüsen und gilt als großes Salz der Klärung und Entschlackung. Es hilft, Verhärtungen und Ablagerungen zu lösen und Belastendes abzubauen. Auf seelischer Ebene steht es für das Auflösen alter Verkrustungen und festgefahrener Muster. Für die Eins, deren Wunde sich als ängstliche Kontrolle und ständige Selbstprüfung zeigt, schafft es Bewegung. So unterstützt es das Lösen innerer Verhärtung hin zu mehr Weichheit und Nachsicht.",
  "Natrium chloratum": "Das Schüßler-Salz Nr. 8 reguliert den Flüssigkeitshaushalt und ist das große Salz des seelischen Gleichgewichts. Es ordnet, wo zu viel oder zu wenig fließt – im Körper wie im Gefühl. Traditionell hilft es, alten Kummer, zurückgehaltene Tränen und verschlucktes Leid zu lösen. Für die Zwei, die sich für andere aufgibt und eigene Bedürfnisse überhört, bringt es heilsamen Ausgleich. So unterstützt es, wieder bei sich selbst aufzutanken, statt sich im Geben zu verlieren.",
  "Ferrum phosphoricum": "Das Schüßler-Salz Nr. 3 ist das Salz der Energie, der Sauerstoffaufnahme und der ersten Abwehrkraft. Es stärkt Widerstandskraft, Initiative und gesunde Tatkraft. Auf seelischer Ebene steht es für Mut und Belastbarkeit, ohne sich zu verausgaben. Für die Drei, die sich über Leistung definiert und Versagen fürchtet, ist es ein kräftigender Begleiter. So unterstützt es echte, getragene Energie statt rastloses Funktionieren unter Hochdruck.",
  "Kalium phosphoricum": "Das Schüßler-Salz Nr. 5 ist das große Nerven- und Energiesalz. Es stärkt bei seelischer und körperlicher Erschöpfung, nährt die Nervenkraft und gibt innere Festigkeit. Traditionell hilft es bei Niedergeschlagenheit, Grübeln und Antriebsschwäche. Für die Vier, die sich in Sehnsucht, Schwermut und dem Gefühl des Andersseins verlieren kann, schenkt es Stabilität. So unterstützt es einen ruhigen, getragenen Boden unter wechselnden Gefühlen.",
  "Calcium phosphoricum": "Das Schüßler-Salz Nr. 2 ist das große Aufbau- und Regenerationssalz für Knochen, Zähne und Zellen. Es stärkt in Phasen von Schwäche, Wachstum und Erschöpfung und gibt neue Kraft. Auf seelischer Ebene steht es für Aufbau, Zuversicht und einen festen Stand. Für die Vier, deren Wunde sich als Gefühl des Mangels und der Heimatlosigkeit zeigt, nährt es Substanz und Halt. So unterstützt es, sich getragen und am eigenen Platz verwurzelt zu fühlen.",
  "Silicea": "Das Schüßler-Salz Nr. 11 ist das Salz des Bindegewebes, der Struktur und der inneren Standfestigkeit. Es stärkt Haut, Haar und Nägel und gibt dem Körper Halt und Form. Auf seelischer Ebene steht es für Rückgrat, Durchhaltevermögen und Selbstvertrauen. Für die Fünf, die sich zum Schutz ihrer Kräfte zurückzieht, gibt es Halt von innen. So unterstützt es, mit eigener Substanz und Festigkeit in Kontakt zu gehen, ohne sich erschöpft zu fühlen.",
  "Magnesium phosphoricum": "Das Schüßler-Salz Nr. 7, die „heiße Sieben“, ist das große Salz der Entspannung und Nervenruhe. Es löst Krämpfe, Anspannung und nervöse Unruhe und beruhigt das überreizte System. Auf seelischer Ebene steht es für Loslassen, Gelassenheit und das Nachlassen innerer Anspannung. Für die Sechs, die in Wachsamkeit, Zweifel und Angst lebt, ist es ein sanfter Beruhiger. So unterstützt es, die ständige innere Alarmbereitschaft loszulassen und Vertrauen zu fassen.",
  "Natrium phosphoricum": "Das Schüßler-Salz Nr. 9 ist das Salz des Säure-Basen-Haushalts und der inneren Balance. Es hilft, Übersäuerung auszugleichen und den Stoffwechsel zu harmonisieren. Auf seelischer Ebene steht es für Maß, Ausgewogenheit und ein gesundes Genug. Für die Sieben, die vor Schmerz in immer neue Reize und Möglichkeiten flieht, bringt es Ausgleich. So unterstützt es, statt rastloser Übersättigung wieder ein ruhiges inneres Gleichgewicht zu finden.",
  "Calcium fluoratum": "Das Schüßler-Salz Nr. 1 verbindet Festigkeit mit Elastizität – es stärkt Bänder, Zahnschmelz und Bindegewebe. Es gibt Struktur, die zugleich beweglich und tragfähig bleibt. Auf seelischer Ebene steht es für Stabilität, die nicht zur Verhärtung wird. Für die Acht, die sich mit Härte und Kontrolle gegen jede Schwäche panzert, ist genau das die Heilrichtung. So unterstützt es echte Kraft, die auch Weichheit und Beweglichkeit zulässt, statt nur zu schützen.",
  "Natrium sulfuricum": "Das Schüßler-Salz Nr. 10 ist das große Salz der Ausscheidung und des Loslassens. Es unterstützt Leber, Galle und die Entgiftung und hilft, Belastendes aus dem System zu schaffen. Auf seelischer Ebene steht es für Klärung, Bewegung und das Verabschieden von Altem. Für die Neun, die sich in Trägheit und Selbstvergessenheit einrichten kann, bringt es heilsamen Antrieb. So unterstützt es, ins Handeln zu kommen und den eigenen Platz aktiv einzunehmen.",
  "Rock Water": "Rock Water ist die Bachblüte für Menschen, die hohe Ideale an sich selbst anlegen und streng, fast asketisch mit sich umgehen. Sie hilft jenen, die sich Genuss und Leichtigkeit versagen, um ein selbstgesetztes Vorbild zu erfüllen. Die Blüte löst innere Härte und starre Selbstdisziplin und bringt Flexibilität und Milde. Für die Eins, die unter dem Druck des inneren Richters steht, ist sie ein sanftes Gegenmittel. So darf aus verbissener Strenge eine offene, freundliche Haltung sich selbst gegenüber werden.",
  "Chicory": "Chicory ist die Bachblüte für eine besitzergreifende, an Bedingungen geknüpfte Form der Liebe. Sie hilft Menschen, die viel geben, dabei aber heimlich Dank, Nähe und Gegenleistung erwarten. Die Blüte wandelt anklammernde Fürsorge in echte, selbstlose Zuwendung. Für die Zwei, die sich über das Gebrauchtwerden definiert, ist sie eine tiefe Heilblüte. So darf Liebe fließen, ohne sich selbst zu verlieren oder etwas zurückzufordern.",
  "Vervain": "Vervain ist die Bachblüte für Übereifer, Begeisterung bis zur Erschöpfung und ständiges inneres Anspannen. Sie hilft Menschen, die mit voller Kraft für ihre Ziele brennen und kaum abschalten können. Die Blüte mildert die Überspannung und bringt Gelassenheit in den Einsatz. Für die Drei, die unter Hochdruck funktioniert und Stillstand fürchtet, ist sie eine wohltuende Entlastung. So darf Begeisterung bleiben, aber ruhiger und maßvoller fließen.",
  "Walnut": "Walnut ist die Bachblüte für Übergänge, Neuanfänge und das Lösen alter Bindungen. Sie schützt vor äußeren Einflüssen und dem Sog fremder Erwartungen, wenn ein neuer Weg ansteht. Die Blüte stärkt die Treue zur eigenen inneren Bestimmung. Für die Drei, deren Wunde sich an fremden Maßstäben von Erfolg orientiert, schafft sie Freiraum. So darf der eigene Wert unabhängig von Anerkennung und äußeren Bildern wachsen.",
  "Sweet Chestnut": "Sweet Chestnut ist die Bachblüte für tiefste seelische Not und das Gefühl äußerster Verlassenheit. Sie ist für Momente, in denen alles dunkel und ausweglos erscheint. Die Blüte bringt Hoffnung und das Vertrauen, dass auch im tiefsten Tal ein Licht entsteht. Für die Vier, die sich in Schwermut und dem Gefühl des Nicht-Dazugehörens verlieren kann, ist sie ein Trost. So darf aus tiefer Verzweiflung wieder Halt und Zuversicht erwachsen.",
  "Willow": "Willow ist die Bachblüte für Groll, Bitterkeit und das Gefühl, vom Leben ungerecht behandelt zu sein. Sie hilft, wenn Selbstmitleid und stiller Vorwurf die Seele verschatten. Die Blüte löst Verbitterung und öffnet wieder für Dankbarkeit und Eigenverantwortung. Für die Vier, deren Wunde sich als schmerzliche Sehnsucht und Vergleich zeigt, bringt sie Erleichterung. So darf aus Groll über das Vermisste eine versöhnliche Annahme des eigenen Lebens werden.",
  "Water Violet": "Water Violet ist die Bachblüte für zurückgezogene, gern allein bleibende Menschen, die Distanz wahren. Sie hilft jenen, die sich still abkapseln und Nähe als anstrengend empfinden. Die Blüte öffnet sanft von kühler Zurückhaltung hin zu warmer Verbundenheit. Für die Fünf, die ihre Kräfte durch Rückzug schützt, ist sie eine Brücke nach außen. So darf aus selbst gewählter Isolation wieder lebendige Teilhabe werden, ohne sich überfordert zu fühlen.",
  "Aspen": "Aspen ist die Bachblüte für unbestimmte Ängste, vages Unbehagen und das Gefühl drohender Gefahr ohne klaren Grund. Sie hilft bei feiner Schreckhaftigkeit und einer reizbaren inneren Wachsamkeit. Die Blüte schenkt Vertrauen und ein Gefühl innerer Sicherheit. Für die Sechs, die mit Zweifel und Angst vor dem Ungewissen lebt, ist sie ein tiefer Beruhiger. So darf an die Stelle diffuser Angst ein stilles Grundvertrauen treten.",
  "Cerato": "Cerato ist die Bachblüte für Menschen, die der eigenen inneren Stimme misstrauen und ständig andere um Rat fragen. Sie hilft jenen, die ihr Wissen haben, aber an ihm zweifeln und sich verunsichern lassen. Die Blüte stärkt das Vertrauen in die eigene Wahrnehmung und Urteilskraft. Für die Sechs, deren Wunde sich als Suche nach Halt im Außen zeigt, ist sie zentral. So darf wieder auf die eigene innere Führung vertraut werden.",
  "Agrimony": "Agrimony ist die Bachblüte für Menschen, die hinter Heiterkeit und Leichtigkeit ihre wahren Sorgen verbergen. Sie hilft jenen, die innere Unruhe und Schmerz mit guter Miene und Ablenkung überdecken. Die Blüte führt zu echtem Frieden, der auch das Schwere zulassen kann. Für die Sieben, die vor Leid in Aktivität und Vorfreude flieht, ist sie eine ehrliche Heilblüte. So darf hinter der fröhlichen Fassade die wahre Empfindung gefühlt und gewandelt werden.",
  "Vine": "Vine ist die Bachblüte für starke, dominante Naturen, die führen, bestimmen und ungern Schwäche zeigen. Sie hilft jenen, deren Kraft leicht in Härte und Kontrolle über andere kippt. Die Blüte wandelt Machtanspruch in eine starke, aber respektvolle und dienende Führung. Für die Acht, die Stärke als Schutz vor Verletzlichkeit braucht, ist sie eine reife Heilrichtung. So darf Kraft führen, ohne zu beherrschen, und Raum für andere lassen.",
  "Oak": "Oak ist die Bachblüte für pflichtbewusste Kämpfernaturen, die unermüdlich weitermachen, auch über ihre Grenzen hinaus. Sie hilft jenen, die niemals aufgeben und sich selbst keine Pause gönnen. Die Blüte lehrt, dass wahre Stärke auch Innehalten und das Annehmen von Grenzen kennt. Für die Acht, deren Wunde Schwäche mit Zerstörung gleichsetzt, ist das eine Befreiung. So darf Kraft mit Pausen und gesunder Nachgiebigkeit gelebt werden.",
  "Wild Rose": "Wild Rose ist die Bachblüte für Resignation, innere Gleichgültigkeit und das Sich-Abfinden mit dem, was ist. Sie hilft jenen, die ohne Klage, aber auch ohne Lebensfreude einfach hinnehmen. Die Blüte weckt neue Lebenslust, Interesse und aktive Teilnahme. Für die Neun, die sich in Trägheit und Selbstvergessenheit verliert, ist sie ein sanfter Funke. So darf aus stiller Ergebung wieder lebendiges, engagiertes Dasein werden.",
  "Amethyst": "Der Amethyst ist eine violette Varietät des Bergkristalls und gilt seit der Antike als Stein der Klarheit, Mäßigung und geistigen Ruhe. Traditionell setzt man ihn dort ein, wo der Kopf nicht zur Ruhe kommt: bei kreisenden Gedanken, innerer Anspannung und einem überaktiven, kritischen Geist. Er wirkt beruhigend, klärend und harmonisierend und unterstützt Meditation wie erholsamen Schlaf. Für die Eins ist er ein Gegengewicht zur strengen Selbstkontrolle und zum unermüdlichen inneren Richter. Er lädt ein, Anspannung loszulassen und echte Gelassenheit zuzulassen – Ruhe statt Verbissenheit, Milde statt Härte gegen sich selbst.",
  "Rosenquarz": "Der Rosenquarz ist der zart-rosa Stein des Herzens schlechthin und seit jeher mit Liebe, Sanftheit und Versöhnung verbunden. Er öffnet das Herz für Mitgefühl, Wärme und Vergebung – und richtet diese liebevolle Haltung ausdrücklich auch nach innen, auf einen selbst. Traditionell hilft er, alten Kummer und Verletzungen sanft zu lösen und wieder Vertrauen in Nähe zu fassen. Für die Zwei, deren Liebe fast immer nach außen strömt, ist er eine stille Erinnerung an die eigene Bedürftigkeit. Er nährt die Selbstliebe und schenkt die Erlaubnis, auch selbst zu empfangen, ohne sich erst nützlich machen zu müssen.",
  "Tigerauge": "Das Tigerauge ist ein goldbraun schimmernder Quarz mit seidigem Lichtspiel und gilt als Stein des Mutes, der Erdung und der klaren Sicht. Es stärkt Selbstvertrauen und Willenskraft und hilft, auch unter Druck Ruhe, Überblick und Standfestigkeit zu bewahren. Traditionell wird es als Schutzstein getragen, der Nervosität, Selbstzweifel und Stress mindert. Für die Drei, deren Wert sich an Leistung und Erfolg zu bemessen scheint, lenkt es den Blick nach innen. So wird erfahrbar, dass echter Wert aus innerer Festigkeit und Klarheit erwächst – nicht allein aus dem nächsten Ziel.",
  "Rhodonit": "Der Rhodonit ist ein rosa-schwarz gemaserter Stein und gilt als großer Helfer bei seelischen Verletzungen. Das Rosa steht für Liebe und Selbstwert, die schwarzen Einschlüsse für die Fähigkeit, auch dunkle Gefühle zu halten und zu wandeln. Er besänftigt alte emotionale Wunden, harmonisiert Stimmungsschwankungen und gibt in inneren Stürmen Halt. Für die Vier, die sich oft anders, fremd und nicht zugehörig fühlt, ist er ein erdender Anker. So führt er aus Schmerz und Sehnsucht in eine ruhige, liebevolle Annahme des eigenen Wertes und der eigenen Geschichte.",
  "Amazonit": "Der Amazonit ist ein türkisgrüner Feldspat und steht für innere Balance, Gelassenheit und Wahrhaftigkeit. Er beruhigt Nerven und kreisende Gedanken, gleicht seelische Wechselbäder aus und schenkt einen klaren, ruhigen Kopf. Zugleich gilt er als Stein der ehrlichen Kommunikation: Er gibt Mut, das eigene Erleben auszusprechen, statt es zurückzuhalten. Für die Fünf, die sich zum Schutz ihrer Kräfte zurückzieht, baut er eine sanfte Brücke nach außen. So hilft er, aus der inneren Beobachterhaltung in echten, lebendigen Kontakt zu treten – ohne Angst, sich dabei zu verlieren.",
  "Hämatit": "Der Hämatit ist ein metallisch glänzender Eisenstein und einer der stärksten Erdungs- und Schutzsteine überhaupt. Sein hoher Eisengehalt steht sinnbildlich für Festigkeit, Widerstandskraft und ein aufrechtes inneres Rückgrat. Er gibt Halt, Stabilität und ein körperlich spürbares Gefühl von Sicherheit und Geborgenheit. Für die Sechs, die in Zweifel, Wachsamkeit und der Suche nach verlässlichem Halt lebt, ist er ein verlässlicher Begleiter. So nährt er Urvertrauen von innen – eine Sicherheit, die nicht von äußeren Garantien abhängt, sondern im eigenen Stand wurzelt.",
  "Rauchquarz": "Der Rauchquarz ist eine rauchig-braune Varietät des Bergkristalls und gilt als ausgleichender Erdungs- und Anti-Stress-Stein. Er hilft, überschüssige, nach vorn drängende Energie zu sammeln, Anspannung abzubauen und Belastendes loszulassen. Traditionell wird er genutzt, um aus Hektik und Überreizung wieder in Ruhe und Gegenwart zu finden. Für die Sieben, die vor Schmerz und Schwere gern nach oben, in Pläne und Möglichkeiten flieht, ist er ein sanftes Gewicht. So bringt er die sprudelnde Unruhe behutsam zurück auf den Boden und macht es leichter, im Hier und Jetzt zu bleiben.",
  "Fluorit": "Der Fluorit ist ein klarer, vielfarbig schimmernder Stein und gilt als Ordnungs- und Klarheitsstein des Geistes. Er hilft, Gedanken zu strukturieren, Konzentration zu bündeln und innere wie äußere Unordnung zu klären. Zugleich gilt er als lösend: Er weicht Härte und Verkrampfung auf und schafft inneren Freiraum. Für die Acht, die sich mit Kontrolle und Stärke gegen jede Schwäche panzert, öffnet er einen sanfteren Weg. So darf hinter der harten Schale wieder Klarheit, Beweglichkeit und ein Stück Weichheit Platz finden – ohne dass sich das bedrohlich anfühlt.",
  "Karneol": "Der Karneol ist ein warm-orange bis rötlich leuchtender Chalcedon und ein klassischer Stein der Lebenskraft, des Mutes und der Tatkraft. Seine warme Farbe steht für Vitalität, Wärme und eine kräftige, fühlbare Präsenz. Er aktiviert, ermutigt und stärkt den eigenen Willen und die Freude am Handeln. Für die Neun, die sich leicht selbst vergisst, einschläft und meint, keine Rolle zu spielen, ist er ein sanfter Weckruf. So hilft er, aus Trägheit und Selbstvergessenheit aufzutauchen, den eigenen Platz einzunehmen und spürbar ins Leben zu treten.",
  "Melissentee": "Melisse ist ein klassisches Heilkraut für Nerven und Gemüt, mild beruhigend und herzstärkend. Ihr zitronig-frischer Duft entspannt, ohne müde zu machen, und löst innere Anspannung. Traditionell wird sie bei Unruhe, Reizbarkeit und nervöser Anspannung getrunken. Für die Eins, die unter innerem Druck und Selbststrenge steht, ist sie ein sanfter Ausgleich. So hilft ein Melissentee, verkrampfte Anspannung loszulassen und zur Ruhe zu kommen.",
  "Rosenblütentee": "Der Rosenblütentee gilt als herzöffnendes, harmonisierendes Getränk voller Sanftheit. Die Rose steht seit jeher für Liebe, Zartheit und seelische Wärme. Traditionell wird sie genutzt, um das Gemüt zu besänftigen und das Herz zu erweichen. Für die Zwei, deren Liebe stets nach außen fließt, ist sie eine zarte Einladung zur Selbstfürsorge. So erinnert ein Rosenblütentee daran, die eigene Wärme auch sich selbst zu schenken.",
  "Rosmarintee": "Rosmarin ist ein belebendes, kräftigendes Kraut, das Kreislauf und Geist anregt. Sein würziger Duft weckt, fördert die Konzentration und gibt frische Tatkraft. Traditionell wird er bei Müdigkeit, Erschöpfung und Antriebsschwäche eingesetzt. Für die Drei, die unter Hochdruck läuft und sich leicht verausgabt, gibt er klare, getragene Energie. So unterstützt ein Rosmarintee belebende Kraft, die aus Frische statt aus Druck kommt.",
  "Weidenröschentee": "Das Weidenröschen ist ein mildes, ausgleichendes Kraut mit besänftigender Wirkung auf das Gemüt. Es gilt als sanfter Begleiter in Phasen innerer Unruhe und seelischer Wechselbäder. Traditionell wird es zur Beruhigung und Harmonisierung getrunken. Für die Vier, die starke Gefühle und Sehnsucht durchlebt, schenkt es einen ruhigen Boden. So hilft ein Weidenröschentee, in den Wogen der Gefühle einen stillen Ausgleich zu finden.",
  "Haferkrauttee": "Haferkraut ist ein klassisches Nervenstärkungs- und Aufbaukraut, besonders bei Erschöpfung. Es nährt und kräftigt die Nerven sanft und gibt neue innere Substanz. Traditionell wird es bei nervöser Schwäche und Auszehrung eingesetzt. Für die Fünf, die ihre Kräfte als knapp erlebt und sich schnell ausgesaugt fühlt, baut es auf. So hilft ein Haferkrauttee, die eigenen Reserven aufzufüllen und gestärkt in Kontakt zu gehen.",
  "Kamillenblütentee": "Die Kamille ist eines der bewährtesten Heilkräuter, beruhigend, entkrampfend und wohltuend. Sie besänftigt Nerven, Magen und Gemüt und gibt ein Gefühl von Geborgenheit. Traditionell wird sie bei Unruhe, Anspannung und Ängstlichkeit getrunken. Für die Sechs, die mit Wachsamkeit und Zweifel lebt, wirkt sie wie eine warme, sichere Umhüllung. So hilft ein Kamillenblütentee, die innere Alarmbereitschaft zu beruhigen und Vertrauen zu fassen.",
  "Pfefferminztee": "Die Pfefferminze ist ein erfrischendes, klärendes Kraut, das Geist und Verdauung anregt. Ihr kühler Duft belebt, schafft Klarheit und löst Schweres und Träges. Traditionell wird sie bei Völlegefühl, Müdigkeit und zur geistigen Erfrischung getrunken. Für die Sieben, deren Geist von Reiz zu Reiz springt, kann sie zugleich klären und sammeln. So hilft ein Pfefferminztee, den überquellenden Kopf zu erfrischen und auf das Wesentliche zu fokussieren.",
  "Ingwertee": "Ingwer ist eine wärmende, kraftvoll anregende Wurzel, die Durchblutung und Lebensfeuer fördert. Ihr scharf-würziger Charakter weckt Energie, Tatkraft und innere Wärme. Traditionell wird sie zur Stärkung, Erwärmung und Belebung eingesetzt. Für die Acht, die voller Kraft und Schutzimpuls ist, passt ihre warme, klare Energie. So hilft ein Ingwertee, die starke Kraft mit Wärme zu verbinden statt mit Härte.",
  "Fencheltee": "Fenchel ist ein mildes, entspannendes und ausgleichendes Kraut mit wohltuender Wirkung. Er beruhigt sanft und harmonisiert, ohne zu dämpfen. Traditionell wird er bei Unruhe und zur Beruhigung des Bauches getrunken. Für die Neun, die Harmonie und Ruhe sucht, ist er ein vertrauter Begleiter – mit dem Hinweis, dass Ruhe nicht in Trägheit kippen muss. So hilft ein Fencheltee, eine entspannte Gelassenheit zu finden, die wach und präsent bleibt.",
};

