    zombie: "EINS war ein Zombie geworden – ein sehr höflicher, angemessener, regelbefolgender Zombie, aber dennoch ein Zombie.",
    text: "Es war einmal ein Mensch namens EINS. Er kam als spontanes, unbeschwertes Kind auf die Welt – eines, das die Fülle des Lebens spürte, die Dinge leicht nahm und frei in den Tag lebte. Er war neugierig, offen und von Natur aus gelassen.\n\nDoch schon früh machte er eine Erfahrung, die alles veränderte: Er wurde kritisiert. Vielleicht nicht einmal böse gemeint – doch es traf das Kind tief. Um dem Schmerz des Beurteilt-werdens zuvorzukommen, begann er, sich selbst zu überwachen. Er verinnerlichte die Maßstäbe der anderen und versuchte fortan, immer richtig zu liegen, immer gut zu sein. Seine innere Überzeugung lautete: Nur wenn ich fehlerfrei bin, bin ich auch liebenswert.\n\nSo entwickelte EINS über die Zeit eine außerordentliche Fähigkeit: Er erkannte Fehler auf den ersten Blick und sah, wie alles noch besser, noch vollkommener sein könnte – bei sich und bei anderen. Er arbeitete hart, hielt sich an alle Regeln des guten Benehmens und beurteilte andere genauso streng wie sich selbst. Tugendhaft zu sein wurde zu seiner Identität.\n\nDoch in diesem Streben nach Perfektion verlor er den Zugang zu sich selbst. Er unterdürckte seine Impulse, seine Kreativität und seine Spontaneität. Er verbarg seinen Zorn und versuchte stattdessen, nett zu bleiben. Er kontrollierte sich und alles um ihn herum – denn ein Fehler fühlte sich innerlich wie Versagen an. Und wenn er doch einmal nicht alles richtig machte, bestrafte er sich selbst.",
