    zombie: "ZWEI war ein Zombie geworden – ein sehr freundlicher, großzügiger, hilfsbereiter Zombie, aber trotzdem ein Zombie.",
    text: "Es war einmal ein Mensch namens ZWEI. Als kleines Kind war er voller Lebensfreude und natürlicher Zuneigung – er liebte es einfach, Menschen zu lieben. Er besaß eine feine emotionale Feingefühligkeit und ein tiefes Bedürfnis, sich geliebt und geborgen zu fühlen.\n\nDoch manchmal blieben seine Bedürfnisse unerfüllt. Wenn er hungrig war, kam niemand. Wenn er verletzt war, bemerkte es keiner. Wenn er Liebe spürte und suchte, fühlte er sich oft nicht erwidert. Das schmerzte.\n\nUm die Liebe zu bekommen, die er so sehr brauchte, versuchte ZWEI, sie selbst zu geben. Er kümmerte sich um andere – in der Hoffnung, dass sie sich dann auch um ihn kümmern würden. Er gab immer mehr, weil er merkte: Je großzügiger ich bin, desto mehr mögen mich die anderen. Seine eigenen Wünsche stellte er hintan, denn wenn er etwas einforderte, könnten die anderen Nein sagen. Und Ablehnung war für ihn das Gegenteil von Liebe.\n\nSo lernte ZWEI, sich ganz auf die Bedürfnisse anderer zu konzentrieren – und vergafß dabei seine eigenen. Er verwandelte sich mit jeder Begegnung in das, was der andere gerade brauchte, und konnte zu niemandem Nein sagen. Sein Bedürfnis, geliebt und wichtig zu sein, wuchs ins Unersättliche – während er für seine eigenen tiefen Gefühle und Bedürfnisse immer tauber wurde.",
